"""Greedy paragraph-preserving text wrapping."""


def wrap(text, width):
    """Fill paragraphs greedily to width; long words stay whole. Raises ValueError if width < 1."""
    if width < 1:
        raise ValueError(f"width must be at least 1, got {width}")
    paragraphs, current = [], []
    for line in text.splitlines():
        if line.strip():
            current.append(line)
        elif current:
            paragraphs.append(current)
            current = []
    if current:
        paragraphs.append(current)
    out = []
    for lines in paragraphs:
        row = ""
        wrapped = []
        for word in " ".join(lines).split():
            if row and len(row) + 1 + len(word) <= width:
                row += " " + word
            else:
                if row:
                    wrapped.append(row)
                row = word
        wrapped.append(row)
        out.append("\n".join(wrapped))
    return "\n\n".join(out)
